// espera a pessoa parar de digitar (filtros de listas grandes): roda fn só depois de ms sem novas chamadas
export function debounce(fn, ms = 150) { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; }
